function hFixture(bool $sla=false,bool $mail=false):array{$f=gFixture($sla,$mail);dGrant($f);$a=$f['db']->execute('SELECT id FROM identity_assignments WHERE user_id=? AND customer_id IS NULL',[$f['admin']['user']])->fetchColumn();$f['db']->execute('INSERT INTO identity_grants(id,assignment_id,permission,customer_scope,department_scope) VALUES (?,?,?,?,?)',[Id::uuid(),$a,'support.ticket.split','*',$f['departments'][0]]);$f['split']=new \Hostider\Support\Split\Commands($f['c']);return $f;}
function hSource(array $f):array{$t=bTicket($f);$reply=bReply($f,$t,client:true);$t['remaining_message']=$reply['message_id'];return $t;}
function hBody(array $f,array $t,?array $ids=null,string $subject='Explicit synthetic split subject'):array{return ['action'=>'split','payload'=>['source_id'=>$t['id'],'version'=>(int)bRow($f,$t)['version'],'message_ids'=>$ids??[$t['message_id']],'subject'=>$subject]];}
function hPrepare(array $f,array $t,?array $ids=null):array{$b=hBody($f,$t,$ids);$p=$f['split']->command($f['admin']['reference'],'prepare',$b,Id::uuid(),Id::uuid());$b['confirmation']=['id'=>$p['id'],'accepted'=>true];return $b;}
