function hSnapshot(array $f):array{$out=[];foreach($f['db']->execute("SELECT table_name FROM information_schema.tables WHERE table_schema=DATABASE() AND (table_name LIKE 'support_%' OR table_name IN ('audit_logs','outbox_events','inbox_events','jobs','idempotency_keys')) ORDER BY table_name")->fetchAll(PDO::FETCH_COLUMN) as $table){$rows=$f['db']->execute('SELECT * FROM `'.$table.'`')->fetchAll();usort($rows,fn($a,$b)=>strcmp(\Hostider\Core\CanonicalJson::encode($a),\Hostider\Core\CanonicalJson::encode($b)));$out[$table]=hash('sha256',\Hostider\Core\CanonicalJson::encode($rows));}return $out;}
function hSourceWork(array $f,array $t):array{$db=$f['db'];return ['work'=>$db->execute('SELECT * FROM support_work_tickets WHERE ticket_id=?',[$t['id']])->fetchAll(),'cycles'=>$db->execute('SELECT * FROM support_sla_cycles WHERE ticket_id=? ORDER BY id',[$t['id']])->fetchAll(),'clocks'=>$db->execute('SELECT c.* FROM support_sla_clocks c JOIN support_sla_cycles y ON y.id=c.cycle_id WHERE y.ticket_id=? ORDER BY c.id',[$t['id']])->fetchAll(),'history'=>$db->execute('SELECT h.* FROM support_sla_history h JOIN support_sla_clocks c ON c.id=h.clock_id JOIN support_sla_cycles y ON y.id=c.cycle_id WHERE y.ticket_id=? ORDER BY h.id',[$t['id']])->fetchAll()];}
function hRace(array $f,array $requests):array{$children=[];foreach($requests as $p){$pipes=[];$proc=proc_open([PHP_BINARY,__DIR__.'/support-split-child.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,null,bEnvironment($f));if(!is_resource($proc)){throw new RuntimeException('SPLIT_CHILD');}fwrite($pipes[0],json_encode($p,JSON_THROW_ON_ERROR));fclose($pipes[0]);$children[]=[$proc,$pipes];}$out=[];foreach($children as [$proc,$pipes]){$raw=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);same(0,proc_close($proc));same('',$err);$out[]=json_decode($raw,true,32,JSON_THROW_ON_ERROR);}return $out;}
